class Node:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None
        self.height = 1

def height(node):
    if not node:
        return 0
    return node.height

def update_height(node):
    node.height = max(height(node.left), height(node.right)) + 1

def balance_factor(node):
    if not node:
        return 0
    return height(node.left) - height(node.right)

def right_rotate(y):
    x = y.left
    T2 = x.right
    x.right = y
    y.left = T2
    update_height(y)
    update_height(x)
    return x

def left_rotate(x):
    y = x.right
    T2 = y.left
    y.left = x
    x.right = T2
    update_height(x)
    update_height(y)
    return y

def insert_to_avl(node, value):
    if not node:
        return Node(value)
    elif value < node.value:
        node.left = insert_to_avl(node.left, value)
    else:
        node.right = insert_to_avl(node.right, value)

    update_height(node)
    bf = balance_factor(node)

    if bf > 1 and value < node.left.value:
        return right_rotate(node)
    if bf < -1 and value > node.right.value:
        return left_rotate(node)
    if bf > 1 and value > node.left.value:
        node.left = left_rotate(node.left)
        return right_rotate(node)
    if bf < -1 and value < node.right.value:
        node.right = right_rotate(node.right)
        return left_rotate(node)

    return node

def insertToAVL(root, value):
    return insert_to_avl(root, value)
